INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.combicham', $ck${"title": "COMBI-CHAM code key – drills and inserts", "subtitle": "Large diameter (26 – 50 mm) MNC drills with a pilot SUMO-CHAM head and peripheral indexable inserts, and their wiper inserts", "example": "MNC 260-130 A32-150-06-5D", "decoder": "combi-cham", "sections": [{"key": "i-family", "title": "Insert – family", "sample": "SOGX", "rows": [{"code": "SOGX", "meaning": "Precision ground peripheral inserts with a wiper"}, {"code": "SOGT", "meaning": "Precision ground peripheral inserts with a wiper"}]}, {"key": "i-size", "title": "Insert – size", "rows": [{"code": "##", "meaning": "Insert size"}]}, {"key": "i-thick", "title": "Insert – thickness", "rows": [{"code": "##", "meaning": "Insert thickness code"}, {"code": "#T#", "meaning": "Insert thickness code with T"}]}, {"key": "i-radius", "title": "Insert – corner radius", "rows": [{"code": "##", "meaning": "Corner radius x10"}]}, {"key": "i-chip", "title": "Insert – chipformer", "rows": [{"code": "W", "meaning": "DT general use chipformer with a wiper"}]}, {"key": "t-family", "title": "Drill – family", "sample": "MNC", "rows": [{"code": "MNC", "meaning": "Large diameter indexable drill with a pilot SUMO-CHAM head"}]}, {"key": "t-dia", "title": "Drill – diameter", "rows": [{"code": "###", "meaning": "Drilling diameter x10 (e.g. 260 = 26.0 mm)"}]}, {"key": "t-length", "title": "Drill – length", "rows": [{"code": "###", "meaning": "Usable length in mm (inferred)"}]}, {"key": "t-shank", "title": "Drill – shank type", "rows": [{"code": "A", "meaning": "One flat shank"}]}, {"key": "t-height", "title": "Drill – shank diameter", "rows": [{"code": "##", "meaning": "Shank diameter in mm (32, 40)"}]}, {"key": "t-pilot", "title": "Drill – pilot head", "rows": [{"code": "###", "meaning": "The pilot SUMO-CHAM ICP head it carries x10 (e.g. 150 = ICP 150)"}]}, {"key": "t-insert", "title": "Drill – peripheral inserts", "rows": [{"code": "##", "meaning": "Size of the SOGX / SOGT inserts (e.g. 06)"}, {"code": "W#", "meaning": "WCGX peripheral inserts of this size (e.g. W5)"}]}, {"key": "t-depth", "title": "Drill – drilling depth", "rows": [{"code": "#D", "meaning": "Drilling depth ratio (5D, 7D, 8D)"}]}]}$ck$)
